/*
 * build_assets.c — Embedded platform library extraction
 *
 * Includes xxd-generated byte arrays for the platform .a and
 * template files. These are generated by the Makefile during
 * the two-stage build: compile → archive → xxd → embed.
 *
 * SPDX-License-Identifier: AGPL-3.0-or-later
 */

#include "hull/build_assets.h"
#include <stdio.h>
#include <string.h>

/* These headers are generated by `make` — xxd of platform .a and templates */
#ifdef HL_BUILD_EMBEDDED
#include "embedded_platform.h"
#include "embedded_templates.h"
#endif
#ifdef HL_BUILD_EMBEDDED_RUNTIME
#include "embedded_runtime.h"   /* hl_embedded_feature_{lua,js}_a[] */
#endif
#ifdef HL_BUILD_EMBEDDED_HTTP
#include "embedded_http.h"      /* hl_embedded_feature_http_a[] */
#endif
#ifdef HL_BUILD_EMBEDDED_TUI
#include "embedded_tui.h"       /* hl_embedded_feature_tui_{lua,js}_a[] */
#endif
#ifdef HL_BUILD_EMBEDDED_WASM
#include "embedded_wasm.h"      /* hl_embedded_feature_wasm{,_lua,_js}_a[] */
#endif

/* ── Helper: write data to a file ──────────────────────────────────── */

/* write_blob is only called from the embedded-platform extraction paths
 * below (tcc is no longer embedded). On a non-embedded build the function is
 * defined-but-unused and -Werror=unused-function kills the build, so gate it
 * on the embedded-platform macros. */
#if defined(HL_BUILD_EMBEDDED) || defined(HL_BUILD_EMBEDDED_MULTIARCH) \
    || defined(HL_BUILD_EMBEDDED_RUNTIME) || defined(HL_BUILD_EMBEDDED_HTTP) \
    || defined(HL_BUILD_EMBEDDED_TUI) || defined(HL_BUILD_EMBEDDED_WASM)
static int write_blob(const char *path, const unsigned char *data, size_t len)
{
    FILE *f = fopen(path, "wb");
    if (!f)
        return -1;
    size_t written = fwrite(data, 1, len, f);
    fclose(f);
    return (written == len) ? 0 : -1;
}
#endif

/* ── Multi-arch platform API ───────────────────────────────────────── */

int hl_build_get_platforms(const HlEmbeddedPlatform **out)
{
#ifdef HL_BUILD_EMBEDDED_MULTIARCH
    if (!out)
        return 0;
    *out = hl_embedded_platforms;
    /* Count entries (excluding sentinel) */
    int n = 0;
    while (hl_embedded_platforms[n].arch)
        n++;
    return n;
#else
    (void)out;
    return 0;
#endif
}

int hl_build_extract_platform_arch(const char *dir, const char *arch)
{
#ifdef HL_BUILD_EMBEDDED_MULTIARCH
    if (!dir || !arch)
        return -1;

    for (int i = 0; hl_embedded_platforms[i].arch; i++) {
        if (strcmp(hl_embedded_platforms[i].arch, arch) == 0) {
            char path[1024];
            int n = snprintf(path, sizeof(path), "%s/libhull_platform.%s.a",
                             dir, arch);
            if (n < 0 || (size_t)n >= sizeof(path))
                return -1;
            return write_blob(path, hl_embedded_platforms[i].data,
                              hl_embedded_platforms[i].len);
        }
    }
    return -1; /* arch not found */
#else
    (void)dir; (void)arch;
    return -1;
#endif
}

/* ── Single / backward-compat extraction ───────────────────────────── */

int hl_build_extract_platform(const char *dir)
{
#ifdef HL_BUILD_EMBEDDED_MULTIARCH
    /* Multi-arch: extract the first entry as libhull_platform.a */
    if (!dir || !hl_embedded_platforms[0].arch)
        return -1;

    char path[1024];
    int pn = snprintf(path, sizeof(path), "%s/libhull_platform.a", dir);
    if (pn < 0 || (size_t)pn >= sizeof(path))
        return -1;
    return write_blob(path, hl_embedded_platforms[0].data,
                      hl_embedded_platforms[0].len);
#elif defined(HL_BUILD_EMBEDDED)
    if (!dir)
        return -1;

    char path[1024];
    int pn = snprintf(path, sizeof(path), "%s/libhull_platform.a", dir);
    if (pn < 0 || (size_t)pn >= sizeof(path))
        return -1;
    return write_blob(path, hl_embedded_platform_a,
                      hl_embedded_platform_a_len);
#else
    (void)dir;
    fprintf(stderr, "hull build: platform library not embedded in this build\n");
    fprintf(stderr, "hint: rebuild hull with `make platform && make EMBED_PLATFORM=1`\n");
    return -1;
#endif
}

int hl_build_extract_feature_runtime(const char *dir, const char *rt)
{
#ifdef HL_BUILD_EMBEDDED_RUNTIME
    if (!dir || !rt)
        return -1;
    const unsigned char *data = NULL;
    unsigned int len = 0;
    if (strcmp(rt, "lua") == 0) {
        data = hl_embedded_feature_lua_a; len = hl_embedded_feature_lua_a_len;
    } else if (strcmp(rt, "js") == 0) {
        data = hl_embedded_feature_js_a;  len = hl_embedded_feature_js_a_len;
    } else {
        return -1;
    }
    char path[1024];
    int n = snprintf(path, sizeof(path), "%s/libhull_feature-%s.a", dir, rt);
    if (n < 0 || (size_t)n >= sizeof(path))
        return -1;
    return write_blob(path, data, len);
#else
    (void)dir; (void)rt;
    return -1;
#endif
}

