int hl_build_get_template(const char **data, size_t *len)
{
#ifdef HL_BUILD_EMBEDDED
    if (!data || !len)
        return -1;
    *data = (const char *)hl_embedded_app_main_c;
    *len = hl_embedded_app_main_c_len;
    return 0;
#else
    (void)data; (void)len;
    return -1;
#endif
}

